"""Stage 4 screens on bounded positions generated by the local FoW referee."""

from collections import Counter, defaultdict
from itertools import product
from statistics import mean

import chess
import fow  # noqa: F401 - exposes the canonical starter referee
import referee

from tools.stage3 import P3, P4, P6, P9


TACTICAL_FAMILIES = {
    "incompatible-escapes": ("c3", "d3"),
    "shared-escape": ("c3", "e3"),
}
ROOTS = ("h1h2", "h1h3")
DEFENDER_REPLY = "g8f8"
ESCAPES = ("a1a2", "a1b1", "a1b2")
ENDGAME_LAYOUTS = (("a1", "h1"), ("c3", "f4"), ("f7", "g6"))
MATRIX_ITERATIONS = 6000


def board_with_pieces(pieces):
    board = referee.FowBoard(None)
    for square, symbol in pieces.items():
        board.set_piece_at(chess.parse_square(square), chess.Piece.from_symbol(symbol))
    return board


def history_result(board):
    """Canonical outcome with repetitions counted from the start of this fixture."""
    key = referee.position_key(board)
    repetitions = Counter([key])
    prior = board.copy()
    while prior.move_stack:
        prior.pop()
        repetitions[referee.position_key(prior)] += 1
    return referee.outcome(board, repetitions)


def value(result, side):
    if result is None or result[0] == "1/2-1/2":
        return 0
    return 1 if result[0] == ("1-0" if side else "0-1") else -1


def add_move(board, uci):
    successor = board.copy()
    successor.push_uci(uci)
    return successor


def color_uci(uci, side):
    if side == chess.WHITE:
        return uci
    move = chess.Move.from_uci(uci)
    return chess.Move(chess.square_mirror(move.from_square),
                      chess.square_mirror(move.to_square)).uci()


def tactical_rows(squares, side):
    boards = [board_with_pieces({"a1": "K", "h1": "Q", "g8": "k", sq: "n"})
              for sq in squares]
    if side == chess.BLACK:
        boards = [board.mirror() for board in boards]
    initial_views = {referee.observation(board, side) for board in boards}
    if len(initial_views) != 1 or any(history_result(board) for board in boards):
        raise ValueError("expected one active initial information set")
    initial_view, = initial_views
    rows = {}
    direct = {}
    visibility = {}
    for root in ROOTS:
        action = color_uci(root, side)
        rows[action], visibility[action] = [], []
        direct_values = []
        for board in boards:
            after_root = add_move(board, action)
            term = history_result(after_root)
            direct_values.append(value(term, side))
            if term or board.is_capture(chess.Move.from_uci(action)):
                raise ValueError("matched root must preserve material and remain active")
            after_reply = add_move(after_root, color_uci(DEFENDER_REPLY, side))
            if history_result(after_reply):
                raise ValueError("fixed defender reply must leave an active escape decision")
            view = referee.observation(after_reply, side)
            visibility[action].append(sum(a == "?" and b != "?"
                                          for a, b in zip(initial_view, view)))
            utilities = {}
            for escape in ESCAPES:
                attempt = color_uci(escape, side)
                utilities[attempt] = value(history_result(add_move(after_reply, attempt)), side)
            rows[action].append((1 / len(boards), view, action, utilities))
        if len(set(direct_values)) != 1:
            raise ValueError("root payoff varies across worlds")
        direct[action] = direct_values[0]
    return [board.fen() for board in boards], rows, direct, visibility


def fixed_action(rows):
    actions = set.intersection(*(set(utilities) for _, _, _, utilities in rows))
    values = {action: sum(mass * utilities[action] for mass, _, _, utilities in rows)
              for action in sorted(actions)}
    selected = max(values, key=values.get)
    return selected, values[selected]


def exact_policy_value(rows):
    """Exhaustively check every feasible deterministic observation policy."""
    groups = defaultdict(list)
    for row in rows:
        groups[row[1:3]].append(row)
    available = [sorted(set.intersection(*(set(row[3]) for row in group)))
                 for group in groups.values()]
    return max(sum(mass * utilities[action]
                   for action, group in zip(candidate, groups.values())
                   for mass, _, _, utilities in group)
               for candidate in product(*available))


def tactical_screens():
    planning, information, resolving = [], [], []
    for family, squares in TACTICAL_FAMILIES.items():
        for side in (chess.WHITE, chess.BLACK):
            fens, rows, direct, visibility = tactical_rows(squares, side)
            fixture = {"family": family, "side": "white" if side else "black",
                       "initial_worlds": fens,
                       "fixed_defender_reply": color_uci(DEFENDER_REPLY, side)}
            # Compare every root's continuation independently to the exhaustive oracle.
            controls = {action: fixed_action(transitions) for action, transitions in rows.items()}
            fallback = max(controls, key=lambda action: controls[action][1])
            candidate = P3.choose_root(rows, fallback=fallback)
            assert P3.choose_root(rows, fallback=fallback, max_cost=0)["root_move"] == fallback
            by_root = {}
            for action, transitions in rows.items():
                exact = exact_policy_value(transitions)
                prototype = candidate["by_move"][action]
                realized = sum(mass * utilities[prototype["policy"][f"{view}|{history}"]]
                               for mass, view, history, utilities in transitions)
                by_root[action] = {
                    "transition_rows": transitions,
                    "exact_observation_policy_value": exact,
                    "candidate_policy": prototype["policy"],
                    "candidate_regret": exact - realized,
                    "fixed_action": controls[action][0],
                    "fixed_action_regret": exact - controls[action][1],
                    "clairvoyant_fusion_gap": prototype["fusion_gap"],
                }
            planning.append({**fixture, "selected_root": candidate["root_move"],
                             "control_root": fallback, "by_root": by_root})

            outcomes = {action: [(mass, view, utilities)
                                 for mass, view, _, utilities in transitions]
                        for action, transitions in rows.items()}
            voi = P4.evaluate_root_actions(outcomes, direct)
            without_voi = P4.evaluate_root_actions(outcomes, direct, beta=0)
            count_control = max(sorted(visibility), key=lambda action: mean(visibility[action]))
            information.append({**fixture, "direct_payoff": direct,
                                "candidate": voi, "feature_off_root": without_voi["selected"],
                                "added_visible_squares_by_world": visibility,
                                "square_count_control_root": count_control})

            # Keep ambiguity fixed: nature may choose the hidden world, then the
            # row policy must play a single distribution over feasible escapes.
            unresolved = rows[color_uci(ROOTS[0], side)]
            if len({view for _, view, _, _ in unresolved}) != 1:
                raise ValueError("robust matrix requires an unresolved information set")
            moves = sorted(unresolved[0][3])
            matrix = [[utilities[action] for _, _, _, utilities in unresolved] for action in moves]
            pure_move, _ = fixed_action(unresolved)
            pure = [int(action == pure_move) for action in moves]
            mixed = P6.solve(matrix, MATRIX_ITERATIONS)
            pure_certificate = P6.certificate(matrix, pure, mixed["col_policy"])
            resolving.append({**fixture, "actions": moves, "payoff_matrix": matrix,
                              "prototype": mixed, "pure_prior_greedy_action": pure_move,
                              "pure_control": pure_certificate})
    return planning, information, resolving


def one_turn_outcomes(board):
    """Independent exhaustive oracle over every legal move and all its replies."""
    side = board.turn
    winning = set()
    reply_count = 0
    moves = sorted(move.uci() for move in referee.fow_moves(board))
    for move in moves:
        intermediate = add_move(board, move)
        terminal = history_result(intermediate)
        if terminal is not None:
            outcomes = [terminal]
        else:
            outcomes = [history_result(add_move(intermediate, reply.uci()))
                        for reply in referee.fow_moves(intermediate)]
            reply_count += len(outcomes)
        if outcomes and all(value(result, side) == 1 for result in outcomes):
            winning.add(move)
    return winning, len(moves), reply_count


def endgame_screen():
    groups = defaultdict(list)
    exact_boards = []
    fixed_layouts = []
    winning_actions = cases = false_certificates = missing_certificates = 0
    singleton_wins = oracle_moves = oracle_replies = terminal = 0

    for king, queen in ENDGAME_LAYOUTS:
        for side in (chess.WHITE, chess.BLACK):
            fixed_layouts.append({"attacker_king_before_color_mirror": king,
                                  "attacker_queen_before_color_mirror": queen,
                                  "side": "white" if side else "black"})
            for defender in chess.SQUARE_NAMES:
                if defender in (king, queen):
                    continue
                board = board_with_pieces({king: "K", queen: "Q", defender: "k"})
                if side == chess.BLACK:
                    board = board.mirror()
                if history_result(board) is not None:
                    terminal += 1
                    continue
                fen, view = board.fen(), referee.observation(board, side)
                expected, counted_moves, counted_replies = one_turn_outcomes(board)
                oracle_moves += counted_moves
                oracle_replies += counted_replies
                groups[(king, queen, side, view)].append((fen, expected))
                exact = P9.certify_referee_one_turn([fen], side)
                actual = set(exact["certified_one_turn_capture_actions"])
                exact_boards.append({"fen": fen, "expected": sorted(expected),
                                     "certificate": sorted(actual)})
                singleton_wins += bool(expected)
                cases += 1
                false_certificates += len(actual - expected)
                missing_certificates += len(expected - actual)

    information_sets = []
    for (king, queen, side, view), members in groups.items():
        fens = [fen for fen, _ in members]
        expected = set.intersection(*(wins for _, wins in members))
        result = P9.certify_referee_one_turn(fens, side)
        actual = set(result["certified_one_turn_capture_actions"])
        winning_actions += len(expected)
        false_certificates += len(actual - expected)
        missing_certificates += len(expected - actual)
        information_sets.append({"defender_hidden_worlds": fens, "view": view,
                                 "expected": sorted(expected), "certificate": result})

    return {"layout_families": fixed_layouts, "terminal_boards_excluded": terminal,
            "active_board_count": cases, "information_set_count": len(information_sets),
            "information_sets": information_sets, "known_world_controls": exact_boards,
            "known_worlds_with_winning_action": singleton_wins,
            "hidden_information_certifiable_actions": winning_actions,
            "false_certificates": false_certificates,
            "missing_certificates": missing_certificates,
            "oracle_root_actions": oracle_moves, "oracle_defender_replies": oracle_replies}


def run():
    planning, information, resolving = tactical_screens()
    endings = endgame_screen()
    planning_roots = [detail for fixture in planning for detail in fixture["by_root"].values()]
    voi_values = [row["instrumental_voi"] for case in information
                  for row in case["candidate"]["information_only"].values()]
    return {
        "P3": {"status": "fixture_screen_complete", "sample_count": len(planning),
               "primary_metric": "mean fixed-blind vs observation-contingent policy regret on fixed referee roots",
               "root_action_count": len(planning_roots),
               "candidate_regret": mean(row["candidate_regret"] for row in planning_roots),
               "fixed_action_regret": mean(row["fixed_action_regret"] for row in planning_roots),
               "fixtures": planning,
               "limitations": "Restricted king moves with one fixed defender reply. This compares "
                              "with a blind continuation, and leaves the matched-CPU eBotI endpoint open."},
        "P4": {"status": "fixture_screen_complete", "sample_count": len(information),
               "primary_metric": "instrumental VOI after quiet, equal-direct-payoff referee moves",
               "maximum_instrumental_voi": max(voi_values), "fixtures": information,
               "limitations": "Matched on immediate terminal utility and material in a fixed-reply "
                              "fixture. Later tactics, genuine opponent response, and playing strength are unmeasured."},
        "P6": {"status": "fixture_screen_complete", "sample_count": len(resolving),
               "primary_metric": "exact exploitability gap and policy security in restricted hidden-world matrices",
               "mean_candidate_duality_gap": mean(case["prototype"]["certificate"]["exploitability_gap"]
                                                   for case in resolving),
               "mean_security_gain": mean(case["prototype"]["certificate"]["row_security_value"]
                                          - case["pure_control"]["row_security_value"] for case in resolving),
               "fixtures": resolving,
               "limitations": "Columns represent adversarial selection of hidden worlds, and both policies "
                              "share the referee utility table. This leaves Stockfish cost, blueprint safety, "
                              "and extensive-form resolution untested."},
        "P9": {"status": "fixture_screen_complete", "sample_count": endings["information_set_count"],
               "primary_metric": "false certificates and certified action coverage for declared one-turn KQvK layouts",
               **endings, "limitations": "Exhaustive only for the declared fixed attacker placements and "
                                         "one own turn. Known-world controls are not hidden-information "
                                         "conversions. Prior history and longer-horizon endgame coverage are open."},
    }
